            aOrbiterE = (aWandererD + RotL64(aScatter, 41U)) + 0x9932A762DC916808ULL;
            aOrbiterA = (((aWandererA + RotL64(aPrevious, 11U)) + RotL64(aCarry, 37U)) + 0xFD361F1D0A1BE8E5ULL) + aTwistOrbiterAssignSaltF[(((255U - aIndex) + 156U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x1760F104E169D4D0ULL;
