            aWandererH = aWandererH ^ (((RotL64(aScatter, 3U) + aOrbiterE) + RotL64(aOrbiterH, 43U)) + aTwistWandererUpdateSaltE[(((255U - aIndex) + 61U)) & S_SALT1]);
            aWandererD = aWandererD + ((((RotL64(aCross, 13U) + RotL64(aOrbiterB, 3U)) + aOrbiterA) + RotL64(aCarry, 39U)) + aTwistWandererUpdateSaltA[(((255U - aIndex) + 204U)) & S_SALT1]);
