            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xD7197942A4F88CE2ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x3B2F0D51F47C1E8BULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 103U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xCCAF7EB7DBB09D8DULL), 53U);
