            aCross = (RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 614U)) & S_BLOCK1], 56U) ^ RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 3661U)) & S_BLOCK1], 13U));
