            aWandererD = aWandererD ^ (((RotL64(aCross, 47U) + RotL64(aOrbiterI, 53U)) + aOrbiterC) + aTwistWandererUpdateSaltC[(((255U - aIndex) + 21U)) & S_SALT1]);
