            aOrbiterI = RotL64((aOrbiterI * 0x06A69C24342D09D1ULL), 21U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterI) + 0xAD138E8A9A27C18FULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 250U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x2E845666D6E7B6D2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x58CC2E7E5447A0BFULL), 37U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x4C16356D076CB1EFULL) + aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 91U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0x0AD538D7108AD311ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x81657AC9B63F5FC5ULL), 47U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x7D74BD22C8C32BEAULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x0B2045AF725C68CEULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x3AA65C2FCAE8AB6BULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x1AAB60F0B0BC4153ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x9BF97DA7C067C566ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((255U - aIndex) + 184U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x58DBEE655E6217D9ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xC8E41AEC8D7F7718ULL;
