            aWandererB = aWandererB + (((RotL64(aPrevious, 48U) + RotL64(aOrbiterH, 52U)) + aOrbiterI) + aKeyRotateBWandererUpdateSaltB[((aIndex + 55U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 53U) + RotL64(aOrbiterI, 35U)) + aOrbiterG);
